<?php
declare(strict_types=1);require_once __DIR__.'/_helper.php';sholat_require_manual();
$sesiId=(int)($_GET['sesi_id']??$_POST['sesi_id']??0);$siswaId=(int)($_GET['siswa_id']??$_POST['siswa_id']??0);$s=sholat_session($pdo,$sesiId);if(!$s){http_response_code(404);exit('Sesi sholat tidak ditemukan.');}
if(($s['status']??'')==='ditutup' || ($s['status_sesi']??'')==='CLOSED'){http_response_code(409);exit('Sesi sholat sudah ditutup dan dikunci. Data tidak dapat diedit.');}
$st=$pdo->prepare('SELECT id,nis,nisn,nama,jk,status FROM siswa WHERE id=? LIMIT 1');$st->execute([$siswaId]);$siswa=$st->fetch();if(!$siswa){http_response_code(404);exit('Siswa tidak ditemukan.');}
$errors=[];$success='';$st=$pdo->prepare('SELECT * FROM absensi_sholat WHERE sesi_id=? AND siswa_id=? LIMIT 1');$st->execute([$sesiId,$siswaId]);$current=$st->fetch();$selected=(string)($current['status']??'');$reason=(string)($current['keterangan']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_valid_csrf();$selected=(string)($_POST['status']??'');$reason=trim((string)($_POST['alasan']??''));
 if(!in_array($selected,['SUDAH','BERHALANGAN'],true))$errors[]='Status tidak valid. Untuk BELUM, biarkan belum ada record absensi.';
 if($selected==='BERHALANGAN' && $siswa['jk']!=='P')$errors[]='Status Berhalangan hanya dapat ditetapkan untuk siswi.';
 if($reason==='')$errors[]='Alasan wajib diisi untuk perubahan manual.';
 if(!$errors){try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT * FROM absensi_sholat WHERE sesi_id=? AND siswa_id=? FOR UPDATE');$st->execute([$sesiId,$siswaId]);$existing=$st->fetch();
  if($existing){$up=$pdo->prepare("UPDATE absensi_sholat SET status=?,waktu_scan=CASE WHEN metode='QR' THEN waktu_scan ELSE NULL END,dicatat_oleh=CASE WHEN metode='QR' THEN dicatat_oleh ELSE ? END,metode='MANUAL',keterangan=? WHERE id=?");$up->execute([$selected,user_id(),$reason,$existing['id']]);$ch=$pdo->prepare('INSERT INTO absensi_sholat_perubahan (absensi_sholat_id,status_lama,status_baru,alasan,diubah_oleh) VALUES (?,?,?,?,?)');$ch->execute([$existing['id'],$existing['status'],$selected,$reason,user_id()]);$id=(int)$existing['id'];}
  else{$ins=$pdo->prepare("INSERT INTO absensi_sholat (sesi_id,siswa_id,status,waktu_scan,dicatat_oleh,metode,keterangan) VALUES (?,?,?,NULL,?,'MANUAL',?)");$ins->execute([$sesiId,$siswaId,$selected,user_id(),$reason]);$id=(int)$pdo->lastInsertId();$ch=$pdo->prepare('INSERT INTO absensi_sholat_perubahan (absensi_sholat_id,status_lama,status_baru,alasan,diubah_oleh) VALUES (?,?,?,?,?)');$ch->execute([$id,null,$selected,$reason,user_id()]);}
  $pdo->commit();sholat_audit($pdo,'MANUAL_STATUS',$id,'Status '.$siswa['nama'].' = '.$selected.'. Alasan: '.$reason);$success='Status sholat berhasil disimpan.';$st=$pdo->prepare('SELECT * FROM absensi_sholat WHERE sesi_id=? AND siswa_id=? LIMIT 1');$st->execute([$sesiId,$siswaId]);$current=$st->fetch();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage();}}
}
$page_title='Atur Status Sholat';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Atur Status Sholat</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content sholat-submodule"><div class="page-header"><div><h1>Atur Status Sholat</h1><p><?=e($s['sholat_nama'])?> · <?=e($s['tanggal'])?></p></div><a class="btn btn-secondary" href="<?=BASE_URL?>sholat/daftar.php?sesi_id=<?=$sesiId?>">Kembali</a></div><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="form-card"><div class="detail-grid"><div><small>NIS</small><strong><?=e($siswa['nis'])?></strong></div><div><small>Nama</small><strong><?=e($siswa['nama'])?></strong></div><div><small>Jenis Kelamin</small><strong><?=e($siswa['jk']==='P'?'Perempuan':'Laki-laki')?></strong></div><div><small>Status Saat Ini</small><strong><?=e($current['status']??'Belum')?></strong></div></div><hr style="border:0;border-top:1px solid #e2e8f0;margin:22px 0"><form method="post"><?=csrf_field()?><input type="hidden" name="sesi_id" value="<?=$sesiId?>"><input type="hidden" name="siswa_id" value="<?=$siswaId?>"><div class="form-grid"><label>Status *<select class="form-control" name="status" required><option value="">- Pilih status -</option><option value="SUDAH" <?=$selected==='SUDAH'?'selected':''?>>Sudah</option><option value="BERHALANGAN" <?=$selected==='BERHALANGAN'?'selected':''?>>Berhalangan</option></select></label><label>Alasan / Keterangan *<input class="form-control" name="alasan" required value="<?=e($reason)?>" placeholder="Contoh: Verifikasi guru"></label></div><div class="info-box"><strong>Catatan privasi:</strong><p>Status <strong>Berhalangan</strong> hanya tersedia untuk siswi dan tidak ditampilkan pada layar publik.</p></div><div class="form-actions"><button class="btn btn-primary">Simpan Status</button><a class="btn btn-secondary" href="<?=BASE_URL?>sholat/daftar.php?sesi_id=<?=$sesiId?>">Batal</a></div></form></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
